 "content": "def transform(grid):
    """Return a 3x3 marker in the color of the largest monochrome component."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    largest = (0, 0)
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen[r][c] = True
            size = 0
            while stack:
                y, x = stack.pop()
                size += 1
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            if size > largest[0]:
                largest = (size, color)
    color = largest[1]
    return [[color] * 3 for _ in range(3)]
